import React, { useState, useEffect } from "react";
import { Link } from 'react-router-dom';


function Subscription() {
    const [subscription, setSubscription] = useState([]);

    useEffect(() => {
        const fetchSubscriptionDetails = async () => {
            try {
                const response = await fetch(`${process.env.REACT_APP_SUBSCRIPTION_SERVICE_URL}/subscription-types`);
                const data = await response.json();
                setSubscription(data);
                console.log(data); // Используем данные напрямую
            } catch (error) {
                console.error('Error fetching subscription details:', error);
            }
        };

        fetchSubscriptionDetails();
    }, []);


    return (
        <div>
            <div className="Sub-plans">
                <h1>Выберите план!</h1>
                <div className="Sub-plan">
                    <div className="Sub-text">
                        <h2>План на 1 месяц</h2>
                        <h2>Цена: 10000 тенге.</h2>
                    </div>
                    <div className="Sub-button">
                        <Link className="button" id="button">10000 тенге</Link>
                    </div>
                </div>
                <div className="Sub-plan">
                    <div className="Sub-text">
                        <h2>План на 3 месяца</h2>
                        <h2>Цена: 24000 тенге.</h2>
                        <h2>ВЫГОДНО!</h2>
                    </div>
                    <div className="Sub-button">
                        <Link className="button" id="button">8000 тенге/месяц</Link>
                        <h4>24000 тенге каждые 3 месяца</h4>
                    </div>

                </div>
                <div className="Sub-plan">
                    <div className="Sub-text">
                        <h2>План на 12 месяцев</h2>
                        <h2>Цена: 90000 тенге.</h2>
                        <h2>ВЫГОДНО!!!</h2>
                    </div>
                    <div className="Sub-button">
                        <Link className="button" id="button">7500 тенге/месяц</Link>
                        <h4>90000 тенге каждые 12 месяцев</h4>
                    </div>

                </div>
            </div>
        </div>
    )
}

export default Subscription;
